function level3(){throw new Error("level3-failure")}function level2(){try{level3()}catch(e){const r=new Error("level2-wrapped");throw r.cause=e,r}}function level1(){try{level2()}catch(e){let r=[e.message],t=e.cause;for(;t;)r.push(t.message),t=t.cause;return r.join(" <- caused by <- ")}}print(level1());try{try{throw new TypeError("inner-type-error")}catch(e){if(e instanceof TypeError)throw new RangeError("rethrown-as-range: "+e.message)}}catch(e){print(e.constructor.name+":",e.message)}